pub fn make_outer(a: Vec<f32>, b: Vec<f32>) -> Vec<Vec<f32>> {
    // Outer product matrix: result[i][j] = a[i] * b[j]
    let m = a.len();
    let n = b.len();

    let mut result: Vec<Vec<f32>> = Vec::with_capacity(m);
    for &ai in a.iter() {
        let mut row = Vec::with_capacity(n);
        for &bj in b.iter() {
            row.push(ai * bj);
        }
        result.push(row);
    }

    result
}